79	/** Opens the trace in a new tab; plain text when no link template is configured. */
80	function TraceLink({ href, children }: { href: string | null; children: ReactNode }) {
81	  if (!href) return <>{children}</>;
82	  return (
83	    <a
84	      href={href}
85	      target="_blank"
86	      rel="noopener noreferrer"
87	      className="inline-flex items-center gap-1 rounded-sm underline-offset-2 hover:text-foreground hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
88	    >
89	      {children}
90	      <ExternalLink aria-hidden className="size-3 shrink-0" />
91	    </a>
92	  );
93	}
94	
95	function NeatlogsLine({ usage, neatlogs }: { usage: TurnUsage; neatlogs: NeatlogsUsage }) {
96	  const title = `Neatlogs trace ${neatlogs.traceId}`;
97	  const href = useTraceLink(neatlogs.traceId);
98	  if (neatlogs.status === "pending") {
99	    return (
100	      <div data-testid="neatlogs-usage" data-status="pending" title={title} className="flex items-center gap-1.5 text-[12px] text-muted-foreground">
101	        <span aria-hidden className="h-1.5 w-1.5 rounded-full bg-muted-foreground/60" style={{ animation: "rkPulse 1.2s ease-in-out infinite" }} />
102	        <TraceLink href={href}>Checking Neatlogs…</TraceLink>
103	      </div>
104	    );
105	  }
106	  if (neatlogs.status === "unavailable" || neatlogs.costUsd === undefined || neatlogs.tokens === undefined) {
107	    return (
108	      <div data-testid="neatlogs-usage" data-status="unavailable" title={title} className="text-[12px] text-muted-foreground">
109	        <TraceLink href={href}>Neatlogs: not available yet</TraceLink>
110	      </div>
111	    );
112	  }
113	  return (
114	    <div
115	      data-testid="neatlogs-usage"
116	      data-status="ready"
117	      title={title}
118	      className="flex items-baseline justify-between gap-2 text-[12.5px]"
119	    >
120	      <span className="text-muted-foreground">
121	        Est. {formatUsd(usage.costUsd)} · {formatTokens(usage.tokens)}
122	      </span>
123	      <span className="tabular-nums text-foreground/85">
124	        <TraceLink href={href}>
125	          Neatlogs {formatUsd(neatlogs.costUsd)} · {formatTokens(neatlogs.tokens)} tokens
126	        </TraceLink>
127	      </span>
128	    </div>
129	  );
